    chapters = {
        {
            chapter = "Coming of Age",
            summary = "Today you come of age in Thendal Grove, on an island that floats in the sky. Ailee Farheart in Thendal Village sends you to Rorian the Dayseeker. The grove has work saved up for you, and wants to see what you're made of.",
            recapAlliance = "Coming of age in Thendal Grove mostly means the village finally hands you the chores it's been saving up. I did a lot of chores.\n\nThe good part came after. Somebody lent me better eyes for a look at the anchor pylon, the thing holding our whole island up in the sky, and Falorne Fallwind showed me how to read the leylines, the gift my line carries. Hard to explain. Like putting your ear to the ground and hearing the island hum.\n\nIt wasn't all humming. Al'Aketh converts were out by the standing stones, goading the wind sprites into a fury. First time I met the cult. Wouldn't be the last.\n\nFor my last trial, Aetheen of the Gales sent me into the ursera caves after the den mother. I came back with her head, and the grove let me go.",
            recapHorde = "Coming of age in Thendal Grove, you learn fast that the grown-ups have been saving chores for you. I'll skip the chores.\n\nWhat I remember is the sky. Ventaari Brightwish took me to the Elemental Convergence to use the skysight, the gift my line carries. You look up, and the sky looks back. That's the best I can do. Somebody lent me better eyes, too, for a look at the anchor pylon that keeps the whole island aloft. You don't think about that much, growing up. You do after.\n\nThen the winds by the standing stones went wild, and it turned out Al'Aketh converts were stirring the sprites up on purpose. My first brush with the cult.\n\nLast came my trial, in the ursera caves, after the den mother. I came back. She didn't.",
            quests = {
                { id = 92460, name = "Coming of Age", npc = "Ailee Farheart", gameVersions = { forever = true } },
                { id = 92461, name = "Harmony in Balance", npc = "Rorian the Dayseeker", gameVersions = { forever = true } },
                { id = 94414, name = "The Anchors of Zephras", npc = "Halaan Hawk-Eye", gameVersions = { forever = true } },
                { id = 92597, name = "Reading the Leylines", npc = "Falorne Fallwind", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92598, name = "The Gift of Skysight", npc = "Ventaari Brightwish", faction = "Horde", gameVersions = { forever = true } },
                { id = 92464, name = "Elemental Unrest", npc = "Rorian the Dayseeker", gameVersions = { forever = true } },
                { id = 92465, name = "Agitators", npc = "Yala Windwatcher", gameVersions = { forever = true } },
                { id = 92469, name = "Return to Rorian", npc = "Yala Windwatcher", gameVersions = { forever = true } },
                { id = 92471, name = "Aetheen of the Gales", npc = "Rorian the Dayseeker", gameVersions = { forever = true } },
                { id = 92470, name = "Foul Matriarch", npc = "Aetheen of the Gales", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "The Next Step",
            summary = "Your trial is behind you, and the grove has taught you what it can. Aetheen of the Gales sends you south to report to Constable Aonda in Shen'dar Village. The Al'Aketh have been busy on the road between.",
            recapAlliance = "On the road to Shen'dar Village I broke up a band of thugs that High Priestess Lorthuna had sent down from the Shrine of Akir. Good warm-up.\n\nIn Shen'dar the constable needed one look at me to know which order I belonged to, and sent me to my elder. Rathiril Sunlance of the High Order sat me down, told me how bad things were for the island, and then asked me to go and run the Windshapers off a place the High Order holds sacred. Which meant beating six of their novice seers.\n\nThat's the orders for you. Both love the island. They just can't stand each other.\n\nThe constable's own errand was refreshingly simple. A bandit called Badwind Bennic had a gang in the cave behind the waterfall. Had.",
            recapHorde = "On the road to Shen'dar Village I broke up a band of thugs that High Priestess Lorthuna had sent down from the Shrine of Akir. Good warm-up.\n\nIn Shen'dar the constable read my lineage at a glance and sent me to my elder, Illaya Amberwind of the Windshapers. Illaya talked a long while about the island's plight. Then about the High Order, whose apprentices were all over a place the Windshapers hold sacred. That part was shorter, and it ended with me beating six of them.\n\nThat's the two orders for you. Both would give anything for the island. Neither would share a bench.\n\nAfter that, clearing bandits out of a cave behind the waterfall felt almost restful.",
            quests = {
                { id = 92472, name = "The Next Step", npc = "Aetheen of the Gales", gameVersions = { forever = true } },
                { id = 92544, name = "Al'Aketh Thugs", npc = "Hanaa Nightwind", gameVersions = { forever = true } },
                { id = 93461, name = "Welcome to Shen'dar Village", npc = "Constable Aonda", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92514, name = "Welcome to Shen'dar Village", npc = "Constable Aonda", faction = "Horde", gameVersions = { forever = true } },
                { id = 92596, name = "The High Order", npc = "Rathiril Sunlance", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92595, name = "The Windshapers", npc = "Illaya Amberwind", faction = "Horde", gameVersions = { forever = true } },
                { id = 94413, name = "A Magical Affront", npc = "Rathiril Sunlance", faction = "Alliance", gameVersions = { forever = true } },
                { id = 94411, name = "Meddlesome Mages", npc = "Illaya Amberwind", faction = "Horde", gameVersions = { forever = true } },
                { id = 92517, name = "The Criminal Element", npc = "Constable Aonda", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "Among the Faithful",
            summary = "The Al'Aketh have a missionary preaching in Shen'dar Village, and Constable Aonda is tired of it. Aonda wants someone inside the cult. Sania Silverstream, also in Shen'dar, can make you look like one of the faithful.",
            recap = "The cult had a missionary preaching in Shen'dar, and the constable was tired of it. So I joined up. Somebody put the Mark of Akir on me, and off I went to Falaath Village, one of the faithful.\n\nMissionary Jasaan preached contrition at me while living lightning strolled up and down the streets like it paid rent there. I nodded in all the right places. What I carried home was enough for the constable to strike first, and my second visit to Falaath went a lot worse for them.\n\nThen the cult hit the western watchtower, and I got there too late. Peacekeeper Vaaniel was dead. There was a bloody note, and among the things it sent me after was a family signet. A Shadowsong signet, for the High Elder in Valanaar.\n\nThe report was the easy part to deliver.",
            quests = {
                { id = 93036, name = "Infiltrating the Cult", npc = "Constable Aonda", gameVersions = { forever = true } },
                { id = 92529, name = "Falaath Village", npc = "Sania Silverstream", gameVersions = { forever = true } },
                { id = 92528, name = "Among the Faithful", npc = "Missionary Jasaan", gameVersions = { forever = true } },
                { id = 92550, name = "Havoc in the Highlands", npc = "Constable Aonda", gameVersions = { forever = true } },
                { id = 93926, name = "The Western Watch", npc = "Constable Aonda", gameVersions = { forever = true } },
                { id = 93927, name = "A Last Request", npc = "Peacekeeper Vaaniel", gameVersions = { forever = true } },
                { id = 92701, name = "To Valanaar", npc = "Constable Aonda", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92579, name = "To Valanaar", npc = "Constable Aonda", faction = "Horde", gameVersions = { forever = true } },
                { id = 93948, name = "Deliver the Signet", npc = "Constable Aonda", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "Two Orders",
            summaryAlliance = "In Valanaar, the island's port, Valennia Stormfist sends you to the head of your order: Elaadrin Evengale, Supreme Magister of the High Order. The Magister has a grand plan for saving Zephras, and a part in it for you.",
            summaryHorde = "In Valanaar, the island's port, Valennia Stormfist sends you to the head of your order: Ayessa Dawnsinger, Grand Skyseer of the Windshapers. The Skyseer has a grand plan for saving Zephras, and a part in it for you.",
            recapAlliance = "The head of my order, the Supreme Magister, had a grand plan and a missing scholar. The scholar was Fillion Flamebreeze, and I found Fillion in a shriekling den, hurt. So I carried that scholar out past everything in there that wanted us both dead. Harder than it sounds. Later I went back in for the Shriekling Matriarch and brought Fillion her head.\n\nFillion's readings were the plan: a way to steer skycutter ships between Skywall and Azeroth. I gathered them again at the standing stones, right under the Windshapers' noses.\n\nThen the cult sent the High Order a box. Inside was Belathaan Brightwish's silvered tongue. I went out and evened the account, and after that the High Order pledged itself to the fight.",
            recapHorde = "The head of my order, the Grand Skyseer, had a grand plan and a broken construct. Riaani Nightwind told me what it was missing: crystallized lightning, an enchanted gyrozephyr and an air construct core. Lovely words. I found the parts. I also found where they pointed, which was straight at the High Order. At Belathaan Brightwish, to be exact.\n\nI caught up with Belathaan on the road to the Shrine of Akir, and we had words. Firm ones.\n\nThen the cult answered in blood. Windshaper novices dead in the highlands. I went out to the lowlands and took ten charms off cultist corpses in return. Not even, but a start, and the Windshapers pledged themselves to the fight, High Order or no High Order.",
            quests = {
                { id = 92699, name = "The Supreme Magister", npc = "Valennia Stormfist", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92700, name = "The Grand Skyseer", npc = "Valennia Stormfist", faction = "Horde", gameVersions = { forever = true } },
                { id = 92709, name = "A Grand Adventure", npc = "Elaadrin Evengale", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92708, name = "A Grand Adventure", npc = "Ayessa Dawnsinger", faction = "Horde", gameVersions = { forever = true } },
                { id = 92727, name = "The Missing Scholar", npc = "Dondallion Whisperwind", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92849, name = "The Missing Scholar", faction = "Alliance", mapID = 2521, x = 0.5330, y = 0.7220, location = "the road west of Valanaar, Zephras Isle", gameVersions = { forever = true } },
                { id = 92850, name = "The Missing Scholar", npc = "Fillion Flamebreeze", faction = "Alliance", mapID = 2521, x = 0.5200, y = 0.6940, location = "the Shriekling Den, Zephras Isle", gameVersions = { forever = true } },
                { id = 99260, name = "Fillion's Mission", npc = "Fillion Flamebreeze", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92840, name = "Catching Wind", npc = "Elaadrin Evengale", faction = "Alliance", gameVersions = { forever = true } },
