                { id = 93746, name = "A Firm Response", npc = "Ayessa Dawnsinger", faction = "Horde", gameVersions = { forever = true } },
                { id = 92834, name = "Avenged Tenfold", npc = "Elaadrin Evengale", faction = "Alliance", gameVersions = { forever = true } },
                { id = 93740, name = "Blood for Blood", npc = "Ayessa Dawnsinger", faction = "Horde", gameVersions = { forever = true } },
                { id = 92860, name = "In Service of Zephras", npc = "Elaadrin Evengale", faction = "Alliance", gameVersions = { forever = true } },
                { id = 92871, name = "In Service of Zephras", npc = "Ayessa Dawnsinger", faction = "Horde", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "The Dark Woods",
            summary = "Lotheluum Starbreeze in Valanaar hasn't heard from the druids of Shadowgale Forest in too long, and in a forest that haunted, quiet is a bad sign. Go north and find Elegael Thornpaw, in the northeast of the woods.",
            recap = "The druids in Shadowgale Forest had gone quiet, and in a haunted forest, quiet is never good news.\n\nThe cult had ambushed their den. Elegael Thornpaw had come through it, barely, and knew who'd done it: Commander Haalien, one of their own circle, gone over to the Al'Aketh. I brought back Haalien's head. Tucked behind the bracer was a torn missive saying somebody in Valanaar was feeding the cult everything it knew.\n\nAfter that I took poultices into the den and went from druid to druid, patching up the ones who could still be patched.\n\nI took the missive home to Valanaar, and the names of the dead.",
            quests = {
                { id = 94484, name = "Unnerving Silence", npc = "Lotheluum Starbreeze", gameVersions = { forever = true } },
                { id = 94493, name = "A Sacrifice in Vain", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
                { id = 94485, name = "Tears of the Lady", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
                { id = 94486, name = "Feathers for Binding", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
                { id = 94488, name = "The Ties That Bind", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
                { id = 94489, name = "The Wounds of Betrayal", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
                { id = 94490, name = "Ripped Missive", location = "Shadowgale Forest, Zephras Isle", gameVersions = { forever = true } },
                { id = 94491, name = "The Fate of the Den", npc = "Elegael Thornpaw", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "The Turncoat",
            summary = "You saw what the cult left of the western watchtower. Now it has turned on the eastern one. Valennia Stormfist sends you to Yorana Windyreed there, in the Gustberry Lowlands, while the tower is still standing.",
            recap = "The cult went for the watchtowers next. At the eastern one the relief force was hanging on by its fingernails, so I went for the cult's healers first. Take away the healers and the brawlers get a lot less brave. Commander Belguilos, a peacekeeper who'd turned Breaker for the cult, went down after that, and so did the assault.\n\nBack in Valanaar the High Elder had a lead: a cultist who wanted out. I found the turncoat's hiding place, and the turncoat in it, already dead, with the assassins still hanging about. Ten fewer by the time I left. Under the body was a damaged blue crystal, still glowing.\n\nWhatever the High Elder got out of that crystal ended all talk of caution. We were going to the Shrine of Akir.",
            quests = {
                { id = 93320, name = "Tower Defense", npc = "Valennia Stormfist", gameVersions = { forever = true } },
                { id = 92642, name = "Disrupting Logistics", npc = "Yorana Windyreed", location = "the eastern watchtower, Zephras Isle", gameVersions = { forever = true } },
                { id = 92645, name = "Breaking the Breaker", npc = "Yorana Windyreed", location = "the eastern watchtower, Zephras Isle", gameVersions = { forever = true } },
                { id = 92880, name = "Return to Valanaar", npc = "Yorana Windyreed", location = "the eastern watchtower, Zephras Isle", gameVersions = { forever = true } },
                { id = 92881, name = "The High Elder's Request", npc = "Valennia Stormfist", gameVersions = { forever = true } },
                { id = 92643, name = "The Turncoat", npc = "Talaanis Shadowsong", gameVersions = { forever = true } },
                { id = 98512, name = "Al'Aketh Assassins", location = "the highlands northwest of Valanaar, Zephras Isle", gameVersions = { forever = true } },
                { id = 92644, name = "Unfortunate News", location = "the turncoat's hideout, Zephras Isle", gameVersions = { forever = true } },
                { id = 94568, name = "The Cult's True Plans", npc = "Talaanis Shadowsong", gameVersions = { forever = true } },
                { id = 92640, name = "Desperate Times", npc = "Talaanis Shadowsong", gameVersions = { forever = true } },
            },
        },
        {
            chapter = "The Final Confrontation",
            summary = "No more caution. The peacekeepers and both orders are marching on the Shrine of Akir, High Priestess Lorthuna's seat, together for once, and they want you with them. Join Valennia Stormfist in the Gustberry Lowlands before the march begins.",
            recapAlliance = "The peacekeepers and both orders marched on the Shrine of Akir together and cut a path to the inner sanctum. Empty. Lorthuna had gone up through a portal into the sky.\n\nSo up we went after her, and the help the orders had sent for arrived from Azeroth, the Kirin Tor and the Earthen Ring both. The high priestess was stopped. But the wards that hid Zephras from Al'Akir were down, and no island holds out against the Windlord in his own realm.\n\nSo the orders went down to Azeroth to look for a way to save it. The High Order took a skycutter to Dalaran, a portal took me on to Stormwind, and before long I was being introduced to the Alliance's leaders, one city at a time.\n\nNot bad for somebody who'd never stood on ground that didn't float.",
            recapHorde = "Both orders and the peacekeepers, side by side for once, fought their way into the Shrine of Akir and found the inner sanctum empty. Lorthuna had slipped through a portal to the spires overhead.\n\nUp we went. Help came from Azeroth, the Earthen Ring and the Kirin Tor, and the high priestess was stopped. But the wards that hid Zephras from Al'Akir were down, and the island couldn't stand against the Windlord in his own realm.\n\nSo the Windshapers took a skycutter down to Mulgore to look for a way to save it, and I went on to Orgrimmar, where Thrall sent me round to meet the rest of the Horde.\n\nFirst time I'd stood on ground that wasn't floating. I kept checking.",
            quests = {
                { id = 93065, name = "Prepare for Battle", npc = "Valennia Stormfist", gameVersions = { forever = true } },
                { id = 92947, name = "Making Our Move", npc = "Valennia Stormfist", location = "Gustberry Lowlands, Zephras Isle", gameVersions = { forever = true } },
                { id = 93958, name = "The Inner Sanctum", npc = "Hyusaa Quickbreeze", location = "Shrine of Akir, Zephras Isle", gameVersions = { forever = true } },
                { id = 93835, name = "Confront Lorthuna", npc = "Valennia Stormfist", faction = "Alliance", location = "Shrine of Akir, Zephras Isle", gameVersions = { forever = true } },
                { id = 92646, name = "Confront Lorthuna", npc = "Valennia Stormfist", faction = "Horde", location = "Shrine of Akir, Zephras Isle", gameVersions = { forever = true } },
                { id = 94369, name = "The Fate of Zephras", npc = "Elaadrin Evengale", faction = "Alliance", gameVersions = { forever = true } },
                { id = 93836, name = "The Fate of Zephras", npc = "Ayessa Dawnsinger", faction = "Horde", gameVersions = { forever = true } },
